INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 1.47, 2002, 1, 2, 126401, 10001, "クローチェ", "2023/06/30 12:00:00", "いらっしゃいませっ♪\nキャラバンコインを使って\n買い物ができますよっ！", -470, "2023/09/22 14:59:59", 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 2.15, 2002, 2, 1, 126401, 10002, "クローチェ", "2023/06/30 12:00:00", "素敵な品が揃ってるので\nたーっくさん買っていって\nくださいねっ♪", -470, "2023/09/22 14:59:59", 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 0, 2002, 2, 2, 126501, 10003, "ライラエル", "2023/06/30 12:00:00", "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", -470, "2023/09/22 14:59:59", 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 0, 2002, 1, 1, 126501, 10004, "ライラエル", "2023/06/30 12:00:00", "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", -470, "2023/09/22 14:59:59", 1);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 0, 2002, 2, 2, 127702, 10005, "リンド", "2023/09/15 15:00:00", "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", -470, "2023/12/22 14:59:59", 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 0, 2002, 2, 2, 127702, 10006, "リンド", "2023/09/15 15:00:00", "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", -470, "2023/12/22 14:59:59", 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 0, 2002, 1, 1, 127802, 10007, "ヴルム", "2023/09/15 15:00:00", "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", -470, "2023/12/22 14:59:59", 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 6.5, 2002, 2, 1, 127802, 10008, "ヴルム", "2023/09/15 15:00:00", "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", -470, "2023/12/22 14:59:59", 2);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 0, 2002, 2, 1, 129602, 10009, "アネモネ", "2023/12/15 15:00:00", "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", -470, "2024/03/22 14:59:59", 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 0, 2002, 2, 1, 129602, 10010, "アネモネ", "2023/12/15 15:00:00", "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", -470, "2024/03/22 14:59:59", 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 0, 2002, 1, 1, 129701, 10011, "ネフィ=ネラ", "2023/12/15 15:00:00", "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", -470, "2024/03/22 14:59:59", 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 6.2, 2002, 2, 1, 129701, 10012, "ネフィ=ネラ", "2023/12/15 15:00:00", "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", -470, "2024/03/22 14:59:59", 3);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 3.1, 2002, 3, 5, 130301, 10013, "カノン", "2024/03/15 15:00:00", "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", -470, "2024/06/22 14:59:59", 4);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 6.15, 2002, 3, 2, 130301, 10014, "カノン", "2024/03/15 15:00:00", "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", -470, "2024/06/22 14:59:59", 4);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 0, 2002, 2, 2, 130401, 10015, "ナーナ", "2024/03/15 15:00:00", "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", -470, "2024/06/22 14:59:59", 4);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 3.35, 2002, 2, 1, 130401, 10016, "ナーナ", "2024/03/15 15:00:00", "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", -470, "2024/06/22 14:59:59", 4);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 0, 2002, 1, 1, 130502, 10017, "ホウオウ", "2024/06/15 15:00:00", "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", -470, "2024/09/22 14:59:59", 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 3.18, 2002, 2, 1, 130502, 10018, "ホウオウ", "2024/06/15 15:00:00", "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", -470, "2024/09/22 14:59:59", 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (3, 0, 0, 2002, 4, 4, 130503, 10019, "ホウオウ", "2024/06/15 15:00:00", "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", -470, "2024/09/22 14:59:59", 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 4.9, 2002, 1, 2, 123301, 10020, "ネア", "2024/06/15 15:00:00", "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", -470, "2024/09/22 14:59:59", 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 4.8, 2002, 1, 2, 123301, 10021, "ネア", "2024/06/15 15:00:00", "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", -470, "2024/09/22 14:59:59", 5);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 4.922, 2002, 3, 1, 133301, 10022, "カリザ", "2024/09/15 15:00:00", "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", -470, "2024/12/22 14:59:59", 6);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 9.638, 2002, 3, 5, 133301, 10023, "カリザ", "2024/09/15 15:00:00", "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", -470, "2024/12/22 14:59:59", 6);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 2.88, 2002, 1, 2, 133401, 10024, "ミーア", "2024/09/15 15:00:00", "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", -470, "2024/12/22 14:59:59", 6);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 4.818, 2002, 5, 1, 133401, 10025, "ミーア", "2024/09/15 15:00:00", "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", -470, "2024/12/22 14:59:59", 6);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 1.78, 2002, 2, 1, 133002, 10026, "グレイス", "2024/12/15 15:00:00", "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", -470, "2025/03/22 14:59:59", 7);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 6.15, 2002, 1, 7, 133002, 10027, "グレイス", "2024/12/15 15:00:00", "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", -470, "2025/03/22 14:59:59", 7);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 4.28, 2002, 6, 2, 133102, 10028, "ヴァイオレット", "2024/12/15 15:00:00", "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", -470, "2025/03/22 14:59:59", 7);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 0, 2002, 1, 1, 133102, 10029, "ヴァイオレット", "2024/12/15 15:00:00", "じめじめした商品は\nございませんので\n安心してお買い求め下さい", -470, "2025/03/22 14:59:59", 7);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 5.53, 2002, 2, 1, 136902, 10030, "ルルィ", "2025/03/15 15:00:00", "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", -470, "2025/06/23 14:59:59", 8);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 6.05, 2002, 9, 7, 136902, 10031, "ルルィ", "2025/03/15 15:00:00", "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", -470, "2025/06/23 14:59:59", 8);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 0, 2002, 2, 1, 137001, 10032, "デュラン", "2025/03/15 15:00:00", "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", -470, "2025/06/23 14:59:59", 8);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 0, 2002, 2, 1, 137001, 10033, "デュラン", "2025/03/15 15:00:00", "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", -470, "2025/06/23 14:59:59", 8);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 0, 2002, 2, 2, 135902, 10034, "サツキ", "2025/06/16 15:00:00", "おう\n好きなもん持ってきな", -470, "2025/09/23 14:59:59", 9);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 4.935, 2002, 1, 6, 135902, 10035, "サツキ", "2025/06/16 15:00:00", "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", -470, "2025/09/23 14:59:59", 9);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 7.441, 2002, 2, 5, 135802, 10036, "ユキノ", "2025/06/16 15:00:00", "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", -470, "2025/09/23 14:59:59", 9);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 0, 2002, 7, 7, 135802, 10037, "ユキノ", "2025/06/16 15:00:00", "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", -470, "2025/09/23 14:59:59", 9);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 2.295, 2002, 2, 2, 130901, 10038, "クルル", "2025/09/16 15:00:00", "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", -470, "2025/12/22 14:59:59", 10);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 6.281, 2002, 1, 6, 130901, 10039, "クルル", "2025/09/16 15:00:00", "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", -470, "2025/12/22 14:59:59", 10);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 5.549, 2002, 2, 1, 137701, 10040, "ヴォルガーノ", "2025/09/16 15:00:00", "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", -470, "2025/12/22 14:59:59", 10);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 2.64, 2002, 3, 6, 137701, 10041, "ヴォルガーノ", "2025/09/16 15:00:00", "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", -470, "2025/12/22 14:59:59", 10);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 7.642, 2002, 7, 4, 132801, 10042, "ライラエル", "2025/12/15 15:00:00", "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", -470, "2026/03/23 11:59:59", 11);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 0, 2002, 1, 1, 132802, 10043, "ライラエル", "2025/12/15 15:00:00", "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", -470, "2026/03/23 11:59:59", 11);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 0, 2002, 1, 1, 134502, 10044, "クローチェ", "2025/12/15 15:00:00", "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", -470, "2026/03/23 11:59:59", 11);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 3.72, 2002, 2, 1, 134501, 10045, "クローチェ", "2025/12/15 15:00:00", "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", -470, "2026/03/23 11:59:59", 11);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 4.991, 2002, 2, 1, 138201, 10046, "ネフィ＝ネラ", "2026/03/16 12:00:00", "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", -470, "2026/06/22 11:59:59", 12);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 3.877, 2002, 1, 4, 138201, 10047, "ネフィ＝ネラ", "2026/03/16 12:00:00", "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", -470, "2026/06/22 11:59:59", 12);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 1.71, 2002, 4, 6, 136001, 10048, "アラクネ", "2026/03/16 12:00:00", "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", -470, "2026/06/22 11:59:59", 12);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 5.32, 2002, 5, 2, 136001, 10049, "アラクネ", "2026/03/16 12:00:00", "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", -470, "2026/06/22 11:59:59", 12);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 3.727, 2002, 9, 4, 135401, 10050, "アネモネ", "2026/06/15 12:00:00", "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", -470, "2026/09/22 11:59:59", 13);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 7.213, 2002, 7, 9, 135401, 10051, "アネモネ", "2026/06/15 12:00:00", "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", -470, "2026/09/22 11:59:59", 13);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 1.874, 2002, 1, 2, 135301, 10052, "クリア", "2026/06/15 12:00:00", "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", -470, "2026/09/22 11:59:59", 13);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 0, 2002, 2, 2, 135301, 10053, "クリア", "2026/06/15 12:00:00", "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", -470, "2026/09/22 11:59:59", 13);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 4.215, 2002, 2, 1, 138001, 10054, "ヴァイオレット", "2026/09/15 12:00:00", "大いなる命、神なる勇魚…\n慈しみの矜持を胸に素敵な\n商品をお売りいたします", -470, "2026/12/22 11:59:59", 14);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 0, 2002, 4, 4, 138001, 10055, "ヴァイオレット", "2026/09/15 12:00:00", "すみません、わたくしの\n手料理は売り切れなのです\nグレイスが、買い占めを…", -470, "2026/12/22 11:59:59", 14);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (1, 0, 5.477, 2002, 6, 1, 138901, 10056, "グレイス", "2026/09/15 12:00:00", "何故かいかがわしいお店と\n勘違いされるんですよね\n騎士氏も？　ヤダへんふし", -470, "2026/12/22 11:59:59", 14);
INSERT INTO `v1_bc07290fbfa8c49b538b3d4b142b5855a2cf4fb231eab675f60518ec30dc7ce8` VALUES (2, 0, 5.743, 2002, 2, 1, 138901, 10057, "グレイス", "2026/09/15 12:00:00", "どうも。グレイスちゃん\n客寄せバージョンですぴょん\n一名様ごあんな～い", -470, "2026/12/22 11:59:59", 14);
